:root {
  --cream: #f5eed8;
  --tan: #e2c87e;
  --brown: #7a4e2d;
  --dark-brown: #3e2208;
  --olive: #5a6b3c;
  --olive-light: #8fa66a;
  --rust: #b84c1e;
  --stamp-done-bg: #d4e8c2;
  --stamp-done-border: #5a6b3c;
  --stamp-empty-bg: #ede8de;
  --stamp-empty-border: #c9b89a;
  --text-muted: #9a7c5e;
  --white: #fff;
}

.passport {
  background-color: var(--cream);
  border: 3px solid var(--brown);
  border-radius: 10px;
  width: 480px;
  padding: 0;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.passport-header {
  background-color: var(--brown);
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
}

.passport-icon {
  font-size: 28px;
  line-height: 1;
}

.passport-title {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.passport-subtitle {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.15em;
  color: var(--tan);
  margin: 0;
}

.passport-name {
  font-size: 18px;
  font-weight: 800;
  color: var(--white);
  margin: 0;
  line-height: 1.1;
}

.passport-badge {
  background-color: var(--tan);
  color: var(--dark-brown);
  font-size: 11px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 20px;
  letter-spacing: 0.05em;
  white-space: nowrap;
}

.passport-body {
  display: flex;
  flex-direction: row;
  gap: 0;
  padding: 14px 16px;
  flex: 1;
}

.rider-info {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding-right: 16px;
  border-right: 2px dashed var(--stamp-empty-border);
}

.info-row {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.info-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--text-muted);
  text-transform: uppercase;
}

.info-value {
  font-size: 14px;
  font-weight: 600;
  color: var(--dark-brown);
}

.stamps-section {
  flex: 1.3;
  padding-left: 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.stamps-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.15em;
  color: var(--text-muted);
  margin: 0;
}

.stamps-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.stamp {
  background-color: var(--stamp-empty-bg);
  border: 2px dashed var(--stamp-empty-border);
  border-radius: 8px;
  padding: 8px 6px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.stamp.stamped {
  background-color: var(--stamp-done-bg);
  border: 2px solid var(--stamp-done-border);
}

.stamp-icon {
  font-size: 20px;
  line-height: 1;
}

.stamp-name {
  font-size: 10px;
  font-weight: 600;
  color: var(--brown);
  text-align: center;
  line-height: 1.2;
}

.stamp.stamped .stamp-name {
  color: var(--olive);
}

.passport-footer {
  background-color: var(--dark-brown);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 16px;
  gap: 8px;
}

.footer-motto {
  font-size: 11px;
  font-style: italic;
  color: var(--tan);
}

.footer-org {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--olive-light);
  white-space: nowrap;
}
